mapper.select:


    left join delivery_sku_override dso on dso.sku_id = sku.id and dso.delivery_point_id = #{deliveryPointId}


    and cs.customer_id = #{customerId}
    and cs.sku_id = #{skuId}
    and cs.status = #{status}

        and ( sku.name like concat('%', #{keyword}, '%')
              or sku.mnemonic_code like concat('%', #{keyword}, '%')
              or cs.alias like concat('%', #{keyword}, '%')
              or cs.customer_code like concat('%', #{keyword}, '%')
              or sku.id in (select sku_id from product_alias where alias like concat('%', #{keyword}, '%'))
              or sku.id in (select sku_id from customer_sku_mapping where customer_id = cs.customer_id and customer_alias like concat('%', #{keyword}, '%'))

              or dso.alias_override like concat('%', #{keyword}, '%')

            )


order by cs.created_at desc

mapper.update:
update customers_sku
alias = #{alias}, unit = #{unit}, min_order_qty = #{minOrderQty}, order_step = #{orderStep}, is_follow_default = #{isFollowDefault}, source_template_id = #{sourceTemplateId}, status = #{status},
where id = #{id}
